# Part 1 of 10 of the MaRDI query formulation_mardi.sparql (see README.md).
# This part decides which items exist; the others add their columns to its rows.
SELECT
?id
(CONCAT("mardi:", STRAFTER(STR(?id), STR(wd:))) AS ?qid)

WHERE {

    VALUES ?id {wd:Q6674596}


}
GROUP BY ?id

# Part 1 of 8 of the MaRDI query quantity_mardi.sparql (see README.md).
# This part decides which items exist; the others add their columns to its rows.
SELECT
?id
(CONCAT("mardi:", STRAFTER(STR(?id), STR(wd:))) AS ?qid)
?class
?qudt_quantitykind_id
?qudt_constant_id

WHERE {

    VALUES ?id {wd:Q6674060 wd:Q6674035 wd:Q6674069 wd:Q6673938 wd:Q6534304 wd:Q6674117 wd:Q6673702 wd:Q7360709}

    {
        ?id wdt:P31 wd:Q6534237.
        BIND("Quantity" AS ?class)
    }
    UNION
    {
        ?id wdt:P31 wd:Q6534245.
        BIND("QuantityKind" AS ?class)
    }

    OPTIONAL {
        ?id wdt:P1654 ?qudt_quantitykind_id
    }

    OPTIONAL {
        ?id wdt:P1693 ?qudt_constant_id
    }
}
GROUP BY ?id ?class ?qudt_quantitykind_id ?qudt_constant_id

# Part 1 of 9 of the MaRDI query model_mardi.sparql (see README.md).
# This part decides which items exist; the others add their columns to its rows.
SELECT
?id
(CONCAT("mardi:", STRAFTER(STR(?id), STR(wd:))) AS ?qid)

WHERE {

    VALUES ?id {wd:Q6674954}


}
GROUP BY ?id

# Part 10 of 10 of the MaRDI query formulation_mardi.sparql (see README.md).
SELECT
?id
(GROUP_CONCAT(DISTINCT CONCAT(?stf, " || ", ?stfl, " || ", ?stfd); SEPARATOR=" <|> ") AS ?similar_to)
(GROUP_CONCAT(DISTINCT CONCAT(?pub, " || ", ?publ, " || ", ?pubd); SEPARATOR=" <|> ") AS ?publication)

WHERE {

    VALUES ?id {wd:Q6674596}

    OPTIONAL {
        ?id wdt:P1691 ?stfraw.
        BIND(CONCAT("mardi:", STRAFTER(STR(?stfraw), STR(wd:))) AS ?stf)

        ?stfraw wdt:P31 wd:Q96183.

        OPTIONAL {
            ?stfraw rdfs:label ?stflraw.
            FILTER (lang(?stflraw) = 'en')
        }
        BIND(COALESCE(?stflraw, "No Label Provided!") AS ?stfl)

        OPTIONAL {
            ?stfraw schema:description ?stfdraw
            FILTER (lang(?stfdraw) = 'en')
        }
        BIND(COALESCE(?stfdraw, "No Description Provided!") AS ?stfd)
    }

    OPTIONAL {
        ?id p:P286 ?statement_p .
        ?statement_p ps:P286 ?pubraw .
        ?statement_p pq:P560 ?role .
        VALUES ?role { wd:Q6672349 wd:Q6672344 wd:Q6672366 wd:Q6775621 wd:Q6480405 }
        BIND(CONCAT("mardi:", STRAFTER(STR(?pubraw), STR(wd:))) AS ?pub)

        OPTIONAL {
            ?pubraw rdfs:label ?publraw.
            FILTER (lang(?publraw) = 'en')
        }
        BIND(COALESCE(?publraw, "No Label Provided!") AS ?publ)

        OPTIONAL {
            ?pubraw schema:description ?pubdraw
            FILTER (lang(?pubdraw) = 'en')
        }
        BIND(COALESCE(?pubdraw, "No Description Provided!") AS ?pubd)
    }
}
GROUP BY ?id

